import{_ as e,o,c as a,ai as d}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Craft graph vs Nx","description":"","frontmatter":{},"headers":[],"relativePath":"guide/testing/craft-graph-vs-nx.md","filePath":"guide/testing/craft-graph-vs-nx.md"}'),r={name:"guide/testing/craft-graph-vs-nx.md"};function s(c,t,n,i,h,p){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="craft-graph-vs-nx" tabindex="-1">Craft graph vs Nx <a class="header-anchor" href="#craft-graph-vs-nx" aria-label="Permalink to &quot;Craft graph vs Nx&quot;">​</a></h1><p>Nx organises the <strong>workspace</strong>. The Craft graph judges the <strong>shape of one app</strong>. They are complementary — comparing <code>depConstraints</code> to <code>assertHttpEndpointUnique</code> is comparing a city plan to a wiring diagram.</p><p><strong>Use Nx when</strong> the constraint is about projects, TypeScript imports, or what CI should rerun. <strong>Use Craft when</strong> the constraint is about who may yield whom, who owns an HTTP endpoint, or whether a route proof stayed armed. <strong>Not instead of</strong> <a href="/craft/guide/testing/architecture.html">architecture rules</a> — this page is the why; that page is the how.</p><div class="tip custom-block"><p class="custom-block-title">They already run together</p><p>The demo suite is an Nx target: <code>npx nx architecture demo</code>. Craft does not replace Nx; it adds a graph Nx cannot see.</p></div><h2 id="two-graphs-two-altitudes" tabindex="-1">Two graphs, two altitudes <a class="header-anchor" href="#two-graphs-two-altitudes" aria-label="Permalink to &quot;Two graphs, two altitudes&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Nx</th><th>Craft</th></tr></thead><tbody><tr><td>Node</td><td>an app or a lib</td><td>a route, a service, a <code>GET users</code>, a <code>craftUnique</code> identity</td></tr><tr><td>Edge</td><td>a TypeScript import (<code>static</code> / <code>dynamic</code> / <code>implicit</code>)</td><td><code>depends-on</code>, <code>provides</code>, <code>calls</code>, <code>writes</code>, <code>checks</code>, …</td></tr><tr><td>Question</td><td>who may import whom, and what should rerun?</td><td>who may yield whom, and who owns this endpoint?</td></tr><tr><td>Enforcement</td><td>ESLint <code>@nx/enforce-module-boundaries</code></td><td>Vitest on the graph (<code>assert*</code>, <code>noExclusiveLink</code>)</td></tr><tr><td>Visualisation</td><td><code>nx graph</code> — projects and tasks, <code>--affected</code></td><td><code>npx craft-graph --format html</code> — a route expanding into services and HTTP</td></tr></tbody></table><p>Nx orchestrates. Craft asserts.</p><h2 id="what-nx-cannot-see" tabindex="-1">What Nx cannot see <a class="header-anchor" href="#what-nx-cannot-see" aria-label="Permalink to &quot;What Nx cannot see&quot;">​</a></h2><p>Nx&#39;s node is a project. Everything inside <code>apps/shop/src</code> is opaque: routes, providers, <code>yield*</code>, HTTP, storage. That is not a bug — the project graph is built to be cheap enough to drive CI. The holes appear as soon as you want to judge an <strong>app</strong>, not a workspace.</p><table tabindex="0"><thead><tr><th>Nx sees</th><th>Nx misses</th><th>Craft counterpart</th></tr></thead><tbody><tr><td><code>demo</code> imports <code>@craft-ng/core</code></td><td><code>yield* CheckoutApi</code> in the same app</td><td><code>depends-on</code></td></tr><tr><td>Tags on a lib (<code>scope:admin</code>)</td><td>Two features that share one app</td><td><code>assertPathBoundaries</code>, <code>noExclusiveLink</code></td></tr><tr><td>A circular import between libs</td><td>A service cycle <code>A → B → A</code> inside one tsconfig</td><td><code>assertNoDependencyCycles</code></td></tr><tr><td>That <code>HttpClient</code> was imported</td><td>That <code>GET users</code> is called from two APIs</td><td><code>assertHttpEndpointUnique</code></td></tr><tr><td>Nothing about storage keys</td><td>Two queries sharing a <code>craftUnique</code> identity</td><td><code>assertCraftUnique</code></td></tr><tr><td>Nothing about unused type aliases</td><td>A commented-out <code>CanRun</code> that still compiles</td><td><code>assertRouteDiProofs</code></td></tr><tr><td>Nothing about <code>computed</code></td><td>A <code>craftComputed</code> that <code>calls</code> a method or <code>writes</code> a <code>source$</code></td><td><code>assertCraftComputedPure</code></td></tr></tbody></table><p>Three consequences follow.</p><p><strong>An edge is an import, not DI.</strong> <code>yield* CheckoutApi</code> does not cross a project boundary. Module-boundary ESLint never fires. The Craft graph records it as <code>depends-on</code>.</p><p><strong>Isolation costs a library.</strong> For <code>depConstraints</code> to protect a feature, that feature must be its own project — barrel, tags, often a build. Craft states the same intention on <strong>folders</strong> and on yield, without extracting forty libs.</p><p><strong>ESLint judges a file.</strong> <code>@nx/enforce-module-boundaries</code> sees one import. <code>assertHttpEndpointUnique</code> and <code>assertRouteDiProofs</code> see the whole graph, including lazy <code>loadChildren</code> collections a parent proof never covers.</p><p>Nx Enterprise Conformance can add workspace rules on the project graph and the file tree. Recreating Craft&#39;s AST analysis (DI, yield, HTTP) there would be rewriting <code>@craft-ng/dev-tools</code>.</p><h2 id="what-craft-cannot-see" tabindex="-1">What Craft cannot see <a class="header-anchor" href="#what-craft-cannot-see" aria-label="Permalink to &quot;What Craft cannot see&quot;">​</a></h2><p>The Craft graph is one TypeScript program (<code>analyzeDependencyGraph</code> takes one tsconfig). It does not become a build system.</p><table tabindex="0"><thead><tr><th>Craft sees</th><th>Craft misses</th><th>Nx counterpart</th></tr></thead><tbody><tr><td>Who yields whom inside an app</td><td>Which projects CI should rerun</td><td>project graph + <code>nx affected</code></td></tr><tr><td>Folder lanes on <code>depends-on</code></td><td>A deep import that bypasses a lib&#39;s <code>index.ts</code></td><td><code>enforce-module-boundaries</code></td></tr><tr><td>A duplicate <code>GET users</code></td><td>Nest imported from a frontend project</td><td><code>bannedExternalImports</code></td></tr><tr><td>A service cycle in <code>apps/shop</code></td><td><code>orders</code> ↔ <code>customers</code> as libs</td><td>circular project dependencies</td></tr><tr><td>Craft/Angular TypeScript</td><td>Python, Nest, assets, configs</td><td>polyglot project graph, implicit deps</td></tr><tr><td>A failing Vitest assertion</td><td>A generator that rewrites the file</td><td>Conformance fix generators</td></tr><tr><td>Seconds of ts-morph analysis</td><td>Millisecond cache hits on unchanged libs</td><td>local / remote computation cache</td></tr></tbody></table><p>The Craft graph <strong>asserts</strong>. The Nx graph <strong>executes</strong>: what to build, test, cache, parallelise. Without Nx (or an equivalent), a green architecture suite does not scale in CI.</p><p><code>assertPathBoundaries</code> protects a modular monolith. It does not split the <strong>task</strong> graph. Changing one feature folder still invalidates the whole app architecture target — analysis reloads the tsconfig, in seconds, not milliseconds.</p><p>Craft is a Craft/Angular analyser. Outside that dialect the graph is empty. Nx tags Nest, React, Python, assets and config files.</p><h2 id="the-overlap" tabindex="-1">The overlap <a class="header-anchor" href="#the-overlap" aria-label="Permalink to &quot;The overlap&quot;">​</a></h2><p>Same intention, different edge.</p><table tabindex="0"><thead><tr><th>Intention</th><th>Nx</th><th>Craft</th><th>Trap</th></tr></thead><tbody><tr><td>This layer must not talk to that one</td><td><code>sourceTag: type:ui</code> → <code>onlyDependOnLibsWithTags: type:util</code></td><td><code>assertPathBoundaries</code> — <code>src/app/ui/**</code> must not <code>depends-on</code> <code>src/app/data/**</code></td><td>Nx requires libs. Craft runs inside one tsconfig, on yield, not on the import.</td></tr><tr><td>No cycles</td><td><code>orders</code> → <code>customers</code> → <code>orders</code> (project imports)</td><td><code>assertNoDependencyCycles</code> on services / <code>craftComputed</code></td><td>A service cycle inside <code>apps/shop</code> is green for Nx and red for Craft.</td></tr><tr><td>See the graph</td><td><code>nx graph --affected</code> (projects or tasks)</td><td><code>craft-graph --format html</code> centred on a route</td><td>One shows who rebuilds. The other shows who injects.</td></tr></tbody></table><p>The <code>assertPathBoundaries</code> helper is the closest cousin of <code>depConstraints</code>. Nx tags <strong>projects</strong> and forbids TypeScript imports. Craft tags <strong>folders</strong> on the Craft graph and forbids <code>depends-on</code> (optionally <code>calls</code>) — including inside one app, where module-boundary ESLint does not run. Setup and examples: <a href="/craft/guide/testing/architecture.html#assertpathboundaries">Architecture rules</a>.</p><h2 id="how-they-complement" tabindex="-1">How they complement <a class="header-anchor" href="#how-they-complement" aria-label="Permalink to &quot;How they complement&quot;">​</a></h2><p>Do not recode <code>depConstraints</code> as Vitest, and do not recode Craft&#39;s AST analysis as an Nx Conformance rule. Each tool stays on its graph.</p><table tabindex="0"><thead><tr><th>Keep Nx for</th><th>Keep Craft for</th></tr></thead><tbody><tr><td>Monorepo layout, tags between libs, public API barrels</td><td>HTTP ownership, <code>craftUnique</code> identities</td></tr><tr><td><code>nx affected</code>, local / remote cache, task graph</td><td>Route DI proofs staying armed</td></tr><tr><td>Banning an npm package by tag</td><td>Pure <code>craftComputed</code>, service-level cycles</td></tr><tr><td>Generators, plugins, polyglot projects</td><td><code>noExclusiveLink</code>, browser-boundary HTTP</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Folder lanes are not affected CI</p><p>Extracting Nx libraries gives you <code>nx affected</code>. It still does not prove a single service owns <code>GET users</code>. <code>assertPathBoundaries</code> keeps features apart inside one app. It still does not slice the task graph. Both layers stay necessary.</p></div><p>The working reference is the demo app: an Nx <code>architecture</code> target that runs Vitest on the Craft graph. Copy that layout from <a href="/craft/guide/testing/architecture.html#setting-it-up">Architecture rules</a>.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/craft/guide/testing/architecture.html">Architecture rules</a> — helpers, catalog, Nx target</li><li><a href="/craft/guide/routing/eslint-rules.html">ESLint rules</a> — local slips the graph cannot autofix</li><li><a href="/craft/guide/concepts/vs-angular.html">What craft adds to Angular</a> — compile-time inventory this graph sits on</li><li><a href="/craft/learn/10-testing.html">Learn: test what you wrote</a></li></ul>',32)])])}const g=e(r,[["render",s]]);export{u as __pageData,g as default};
